import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
const cors={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type"};
serve((req:Request)=>req.method==="OPTIONS"?new Response("ok",{headers:cors}):new Response(JSON.stringify({success:false,error:"Photo verification temporarily unavailable. Please retry later."}),{status:503,headers:{...cors,"Content-Type":"application/json"}}));
